          },
          "consumers": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "消费方标识：引擎函数名或组件文件"
          },
          "affects": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "（可选）受影响的呈现区域/选择器"
